    if return_type:
      packet_info = BasicCommandRT()
    else:
      packet_info = BasicCommandCT()
    packet = None
    if packet_header.type == ES_DT_Command:
      packet_info.unpack(data)
    if False:
      pass
    elif packet_header.type == ES_DT_NivelResult:
      packet = NivelResultT()
